const listSubtreeLineIDs = `-- name: ListSubtreeLineIDs :many
WITH RECURSIVE sub(line_id, depth) AS (
    SELECT b.line_id, 1 FROM tangent_branch b WHERE b.parent_line_id = $1
    UNION ALL
    SELECT b.line_id, sub.depth + 1 FROM tangent_branch b JOIN sub ON b.parent_line_id = sub.line_id
    WHERE sub.depth < $2::int
)
SELECT sub.line_id::uuid FROM sub
`

type ListSubtreeLineIDsParams struct {
	ParentLineID uuid.UUID `json:"parent_line_id"`
	MaxDepth     int32     `json:"max_depth"`
}

